(function() {
    'use strict';

    class HumanCapitalAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Human Capital Strategy';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleKey: 'r1_title',
                    briefingKey: 'r1_briefing',
                    d1: { labelKey: 'r1_d1_label', options: [
                        { value: 1, key: 'r1_d1_opt1' },
                        { value: 2, key: 'r1_d1_opt2' },
                        { value: 3, key: 'r1_d1_opt3' }
                    ]},
                    d2: { labelKey: 'r1_d2_label', options: [
                        { value: 1, key: 'r1_d2_opt1' },
                        { value: 2, key: 'r1_d2_opt2' },
                        { value: 3, key: 'r1_d2_opt3' }
                    ]},
                    d3: { labelKey: 'r1_d3_label', options: [
                        { value: 1, key: 'r1_d3_opt1' },
                        { value: 2, key: 'r1_d3_opt2' },
                        { value: 3, key: 'r1_d3_opt3' }
                    ]},
                    d4: { labelKey: 'r1_d4_label', hintKey: 'r1_d4_hint' }
                },
                {
                    titleKey: 'r2_title',
                    briefingKey: 'r2_briefing',
                    d1: { labelKey: 'r2_d1_label', options: [
                        { value: 1, key: 'r2_d1_opt1' },
                        { value: 2, key: 'r2_d1_opt2' },
                        { value: 3, key: 'r2_d1_opt3' }
                    ]},
                    d2: { labelKey: 'r2_d2_label', options: [
                        { value: 1, key: 'r2_d2_opt1' },
                        { value: 2, key: 'r2_d2_opt2' },
                        { value: 3, key: 'r2_d2_opt3' }
                    ]},
                    d3: { labelKey: 'r2_d3_label', options: [
                        { value: 1, key: 'r2_d3_opt1' },
                        { value: 2, key: 'r2_d3_opt2' },
                        { value: 3, key: 'r2_d3_opt3' }
                    ]},
                    d4: { labelKey: 'r2_d4_label', hintKey: 'r2_d4_hint' }
                },
                {
                    titleKey: 'r3_title',
                    briefingKey: 'r3_briefing',
                    d1: { labelKey: 'r3_d1_label', options: [
                        { value: 1, key: 'r3_d1_opt1' },
                        { value: 2, key: 'r3_d1_opt2' },
                        { value: 3, key: 'r3_d1_opt3' }
                    ]},
                    d2: { labelKey: 'r3_d2_label', options: [
                        { value: 1, key: 'r3_d2_opt1' },
                        { value: 2, key: 'r3_d2_opt2' },
                        { value: 3, key: 'r3_d2_opt3' }
                    ]},
                    d3: { labelKey: 'r3_d3_label', options: [
                        { value: 1, key: 'r3_d3_opt1' },
                        { value: 2, key: 'r3_d3_opt2' },
                        { value: 3, key: 'r3_d3_opt3' }
                    ]},
                    d4: { labelKey: 'r3_d4_label', hintKey: 'r3_d4_hint' }
                },
                {
                    titleKey: 'r4_title',
                    briefingKey: 'r4_briefing',
                    d1: { labelKey: 'r4_d1_label', options: [
                        { value: 1, key: 'r4_d1_opt1' },
                        { value: 2, key: 'r4_d1_opt2' },
                        { value: 3, key: 'r4_d1_opt3' }
                    ]},
                    d2: { labelKey: 'r4_d2_label', options: [
                        { value: 1, key: 'r4_d2_opt1' },
                        { value: 2, key: 'r4_d2_opt2' },
                        { value: 3, key: 'r4_d2_opt3' }
                    ]},
                    d3: { labelKey: 'r4_d3_label', options: [
                        { value: 1, key: 'r4_d3_opt1' },
                        { value: 2, key: 'r4_d3_opt2' },
                        { value: 3, key: 'r4_d3_opt3' }
                    ]},
                    d4: { labelKey: 'r4_d4_label', hintKey: 'r4_d4_hint' }
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 50000000,
                    employeeCount: 512,
                    brandScore: 55,
                    eNPS: 22,
                    turnoverRate: 18.4,
                    capabilityScore: 35,
                    revenuePerEmployee: 180000,
                    diversityIndex: 4.5,
                    managerQuality: 45,
                    onboardingQuality: 30,
                    hireQuality: 0,
                    survivorEngagement: 0,
                    legalRisk: 0,
                    scoreHistory: [],
                    eNPSHistory: [],
                    turnoverHistory: [],
                    brandHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    strategicChoice: 1,
                    investmentLevel: 2,
                    approach: 2,
                    budgetAllocation: 50
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            if ((state.currentPeriod || 1) > this.ROUNDS.length) { this._renderCompletion(t); return; }
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefingKey);

            var selects = [
                { labelId: 'decision1Label', selectId: 'strategicChoiceInput', config: round.d1 },
                { labelId: 'decision2Label', selectId: 'investmentLevelInput', config: round.d2 },
                { labelId: 'decision3Label', selectId: 'approachInput', config: round.d3 }
            ];

            selects.forEach(function(item) {
                var lbl = document.getElementById(item.labelId);
                var sel = document.getElementById(item.selectId);
                if (lbl) lbl.textContent = t(item.config.labelKey);
                if (sel) {
                    sel.innerHTML = '';
                    item.config.options.forEach(function(opt) {
                        var o = document.createElement('option');
                        o.value = opt.value;
                        o.textContent = t(opt.key);
                        sel.appendChild(o);
                    });
                }
            });

            var lbl4 = document.getElementById('decision4Label');
            if (lbl4) lbl4.textContent = t(round.d4.labelKey);
            var hint4 = document.getElementById('decision4Hint');
            if (hint4) hint4.textContent = t(round.d4.hintKey);
        }

        _renderCompletion(t) {
            var controls = document.querySelector('.hcstrategy-sim-controls');
            if (controls) controls.style.display = 'none';
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t('sim_complete_title');
            var briefEl = document.getElementById('briefingText');
            if (!briefEl) return;
            var sim = window.mySimulation;
            var html = '<p>' + t('sim_complete_body') + '</p>';
            if (sim && sim.history && typeof this.getPerformanceSummary === 'function') {
                var s = this.getPerformanceSummary(sim.history);
                html += '<p><strong>' + t('final_grade_label') + ':</strong> ' + s.performance +
                        ' (' + t('composite_label') + ' ' + s.compositeScore + '/100)</p>';
                if (s.insights && s.insights.length) {
                    html += '<ul>';
                    for (var i = 0; i < s.insights.length; i++) html += '<li>' + s.insights[i] + '</li>';
                    html += '</ul>';
                }
            }
            briefEl.innerHTML = html;
        }

        validateDecisions(decisions) {
            if (window.mySimulation && window.mySimulation.state &&
                window.mySimulation.state.currentPeriod > this.ROUNDS.length) {
                return false;
            }

            var sel1 = document.getElementById('strategicChoiceInput');
            if (sel1) decisions.strategicChoice = parseInt(sel1.value);

            var sel2 = document.getElementById('investmentLevelInput');
            if (sel2) decisions.investmentLevel = parseInt(sel2.value);

            var sel3 = document.getElementById('approachInput');
            if (sel3) decisions.approach = parseInt(sel3.value);

            var numInput = document.getElementById('budgetAllocationInput');
            if (numInput) decisions.budgetAllocation = parseInt(numInput.value);

            if (isNaN(decisions.budgetAllocation) || decisions.budgetAllocation < 0 || decisions.budgetAllocation > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var quarterCost = 0;
            var quarterScore = 0;
            var eventSummary = '';

            if (period === 1) {
                var evpBrand = [0, 12, 8, 10][d.strategicChoice];
                var evpENPS = [0, 0, 4, 2][d.strategicChoice];
                var evpDiversity = [0, 0, 0.3, 1.5][d.strategicChoice];

                var hireQuality = [0, 55, 70, 88][d.investmentLevel];
                var newHires = [0, 85, 70, 55][d.investmentLevel];
                var selectionCost = [0, 400000, 650000, 950000][d.investmentLevel];

                var onboardQuality = [0, 40, 65, 85][d.approach];
                var onboardCost = [0, 200000, 450000, 720000][d.approach];

                var channelBonus = d.budgetAllocation * 0.1;

                quarterCost = 2400000 + selectionCost + onboardCost;

                ds.brandScore = Math.min(100, Math.round(ds.brandScore + evpBrand + channelBonus));
                ds.eNPS = Math.min(80, Math.round(ds.eNPS + evpENPS + (onboardQuality - 50) * 0.08));
                ds.diversityIndex = Math.min(10, Math.round((ds.diversityIndex + evpDiversity) * 10) / 10);
                ds.onboardingQuality = onboardQuality;
                ds.hireQuality = hireQuality;
                ds.employeeCount += newHires;
                ds.turnoverRate = Math.max(5, Math.round((ds.turnoverRate - (onboardQuality - 30) * 0.06) * 10) / 10);
                ds.budget -= quarterCost;

                quarterScore = Math.round(
                    (ds.brandScore / 100) * 30 +
                    (hireQuality / 100) * 35 +
                    (onboardQuality / 100) * 25 +
                    (d.budgetAllocation / 100) * 10
                );

            } else if (period === 2) {
                var capBonus = [0, 8, 4, 6][d.strategicChoice];
                var careerENPS = [0, 4, 1, 6][d.strategicChoice];
                var careerDiv = [0, 0.2, 0, 0.5][d.strategicChoice];

                var mgrBonus = [0, 0, 10, 25][d.investmentLevel];
                var mgrCost = [0, 0, 268800, 1184000][d.investmentLevel];

                var ldCap = [0, 10, 7, 8][d.approach];
                var ldENPS = [0, 0, 5, 3][d.approach];
                var ldTurnover = [0, 0, -2, -1][d.approach];

                var stratBonus = d.budgetAllocation * 0.12;
                quarterCost = 3800000 + mgrCost;

                ds.capabilityScore = Math.min(100, Math.round(ds.capabilityScore + capBonus + ldCap + stratBonus));
                ds.managerQuality = Math.min(100, Math.round(ds.managerQuality + mgrBonus));
                ds.eNPS = Math.min(80, Math.round(ds.eNPS + careerENPS + ldENPS));
                ds.turnoverRate = Math.max(5, Math.round((ds.turnoverRate + ldTurnover) * 10) / 10);
                ds.diversityIndex = Math.min(10, Math.round((ds.diversityIndex + careerDiv) * 10) / 10);
                ds.budget -= quarterCost;

                if (ds.onboardingQuality < 50) {
                    ds.turnoverRate = Math.round((ds.turnoverRate + 3) * 10) / 10;
                    eventSummary = window.mySimulation.t('event_onboard_debt');
                }

                var revGrowth = Math.round(ds.capabilityScore * 400);
                ds.revenuePerEmployee += revGrowth;

                quarterScore = Math.round(
                    (ds.capabilityScore / 100) * 30 +
                    (ds.managerQuality / 100) * 25 +
                    (Math.max(0, 30 - ds.turnoverRate) / 25) * 25 +
                    (d.budgetAllocation / 100) * 20
                );

            } else if (period === 3) {
                var compTurnover = [0, -5, -2, 1][d.strategicChoice];
                var compCost = [0, 5000000, 2500000, -1000000][d.strategicChoice];
                var compENPS = [0, 3, 1, -2][d.strategicChoice];

                var eqRetention = [0, 2, 5, 3][d.investmentLevel];
                var eqCost = [0, 1200000, 2000000, 800000][d.investmentLevel];

                var retTurnover = [0, -2, -4, -6][d.approach];
                var retENPS = [0, 1, 5, 7][d.approach];
                var retCost = [0, 800000, 500000, 1200000][d.approach];

                var nonMonCost = Math.round(1600000 * (d.budgetAllocation / 100));
                var nonMonENPS = d.budgetAllocation * 0.06;

                if (d.strategicChoice === 3 && d.budgetAllocation > 60) {
                    compTurnover = -2;
                    compENPS = 3;
                }

                quarterCost = (compCost > 0 ? compCost : 0) + eqCost + retCost + nonMonCost;
                if (compCost < 0) ds.budget -= compCost;

                ds.turnoverRate = Math.max(5, Math.round((ds.turnoverRate + compTurnover + retTurnover - eqRetention * 0.3) * 10) / 10);
                ds.eNPS = Math.min(80, Math.round(ds.eNPS + compENPS + retENPS + nonMonENPS));
                ds.budget -= quarterCost;

                if (ds.managerQuality < 50) {
                    ds.eNPS = Math.round(ds.eNPS - 5);
                    ds.turnoverRate = Math.round((ds.turnoverRate + 2) * 10) / 10;
                    eventSummary = window.mySimulation.t('event_manager_debt');
                }

                quarterScore = Math.round(
                    (Math.max(0, 30 - ds.turnoverRate) / 25) * 30 +
                    (Math.max(0, ds.eNPS + 20) / 100) * 30 +
                    (d.budgetAllocation / 100) * 20 +
                    (eqRetention / 5) * 20
                );

            } else if (period === 4) {
                var reducedCount = Math.round(ds.employeeCount * 0.2);
                ds.employeeCount -= reducedCount;

                var legalRisk = [0, 10, 35, 15][d.strategicChoice];
                var capImpact = [0, -12, -3, -2][d.strategicChoice];
                var survBase = [0, 55, 65, 72][d.strategicChoice];

                var sevCost = [0, reducedCount * 15000, reducedCount * 40000, reducedCount * 75000][d.investmentLevel];
                var sevEng = [0, -10, 5, 15][d.investmentLevel];

                var commEng = [0, 20, 8, -5][d.approach];
                var commBrand = [0, 5, -2, -12][d.approach];

                var reEngBonus = d.budgetAllocation * 0.25;
                var reEngCost = Math.round(ds.budget * 0.08 * (d.budgetAllocation / 100));

                var eNPSPenalty = ds.eNPS < 25 ? -10 : 0;
                if (ds.managerQuality < 50) {
                    commEng = Math.round(commEng * 0.6);
                }

                var survivorEng = Math.min(100, Math.max(0, Math.round(survBase + sevEng + commEng + reEngBonus + eNPSPenalty)));

                quarterCost = sevCost + reEngCost;
                ds.budget -= quarterCost;
                ds.capabilityScore = Math.max(0, Math.round(ds.capabilityScore + capImpact));
                ds.brandScore = Math.max(0, Math.min(100, Math.round(ds.brandScore + commBrand - 5)));
                ds.survivorEngagement = survivorEng;
                ds.legalRisk = legalRisk;

                var postTurnover = Math.max(5, Math.round((30 - survivorEng * 0.22) * 10) / 10);
                ds.turnoverRate = postTurnover;
                ds.eNPS = Math.round(survivorEng * 0.7 - 15);

                var legalCost = 0;
                if (legalRisk > 25) {
                    legalCost = Math.round(2400000 * (legalRisk / 100));
                    ds.budget -= legalCost;
                    eventSummary = window.mySimulation.t('event_legal_challenge');
                }

                quarterScore = Math.round(
                    (survivorEng / 100) * 35 +
                    ((100 - legalRisk) / 100) * 20 +
                    ((100 - postTurnover) / 100) * 25 +
                    (d.budgetAllocation / 100) * 20
                );
            }

            ds.scoreHistory.push(quarterScore);
            ds.eNPSHistory.push(ds.eNPS);
            ds.turnoverHistory.push(ds.turnoverRate);
            ds.brandHistory.push(ds.brandScore);

            var results = {
                period: period,
                quarterScore: quarterScore,
                brandScore: ds.brandScore,
                eNPS: ds.eNPS,
                turnoverRate: ds.turnoverRate,
                capabilityScore: ds.capabilityScore,
                employeeCount: ds.employeeCount,
                budget: ds.budget,
                quarterCost: quarterCost,
                eventSummary: eventSummary
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 400);

            return results;
        }

        setupUI(uiManager) {
            var maxP = this.ROUNDS.length;
            uiManager.bind('currentDay', 'currentPeriod', function(v) { return Math.min(v, maxP); });
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budget',
                function(v) { return '$' + (Math.round(v / 100000) / 10).toLocaleString() + 'M'; });
            uiManager.bind('employeeDisplay', 'domainState.employeeCount');
            uiManager.bind('brandDisplay', 'domainState.brandScore',
                function(v) { return v + '/100'; });
            uiManager.bind('enpsDisplay', 'domainState.eNPS');
            uiManager.bind('turnoverDisplay', 'domainState.turnoverRate',
                function(v) { return v + '%'; });
            uiManager.bind('capabilityDisplay', 'domainState.capabilityScore',
                function(v) { return v + '%'; });
            var cv = document.getElementById('performanceChart');
            if (cv) { cv.setAttribute('role', 'img'); cv.setAttribute('aria-label', (window.mySimulation ? window.mySimulation.t('chart_aria') : 'Performance chart')); }
        }

        getChartConfig() {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            return {
                performanceChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: t('ds_score'),
                                data: [],
                                borderColor: '#1a3a5c',
                                backgroundColor: 'rgba(26,58,92,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: t('ds_enps'),
                                data: [],
                                borderColor: '#e67e22',
                                backgroundColor: 'rgba(230,126,34,0.05)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: t('ds_turnover'),
                                data: [],
                                borderColor: '#e74c3c',
                                backgroundColor: 'rgba(231,76,60,0.05)',
