        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) { return 'Q' + (i + 1); });
            return {
                performanceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.scoreHistory },
                        { data: state.domainState.eNPSHistory },
                        { data: state.domainState.turnoverHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.quarterScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var avgScore = Math.round(totalScore / scores.length);

            var lastState = history[history.length - 1];
            var finalBrand = lastState.results ? lastState.results.brandScore || 0 : 0;
            var finalENPS = lastState.results ? lastState.results.eNPS || 0 : 0;
            var finalTurnover = lastState.results ? lastState.results.turnoverRate || 20 : 20;

            var talentQuality = Math.round(scores[0] * 0.6 + (scores[1] || 0) * 0.4);
            var orgHealth = Math.round(Math.max(0, finalENPS + 20) + Math.max(0, 30 - finalTurnover) * 2);
            var capReadiness = lastState.results ? lastState.results.capabilityScore || 0 : 0;
            var financialEff = Math.round(Math.max(0, (lastState.results ? lastState.results.budget || 0 : 0) / 500000));
            var crisisResilience = scores[3] || 0;

            var composite = Math.round(
                talentQuality * 0.25 +
                Math.min(100, orgHealth) * 0.25 +
                capReadiness * 0.20 +
                Math.min(100, financialEff) * 0.20 +
                crisisResilience * 0.10
            );

            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var performance = t('perf_needs');
            if (composite > 70) performance = t('perf_excellent');
            else if (composite > 55) performance = t('perf_good');
            else if (composite > 40) performance = t('perf_developing');

            var insights = [];
            if (finalTurnover > 15) insights.push(t('insight_turnover'));
            if (finalENPS < 20) insights.push(t('insight_enps'));
            if (capReadiness < 50) insights.push(t('insight_cap'));
            if (finalBrand < 50) insights.push(t('insight_brand'));
            if (composite > 60) insights.push(t('insight_strong'));
            if (insights.length === 0) insights.push(t('insight_generic'));

            return {
                totalScore: totalScore,
                averageScore: avgScore,
                compositeScore: composite,
                talentQuality: talentQuality,
                orgHealth: Math.min(100, orgHealth),
                capReadiness: capReadiness,
                financialEfficiency: Math.min(100, financialEff),
                crisisResilience: crisisResilience,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.eventSummary) return results.eventSummary;
            if (state.domainState.brandScore < 45) return window.mySimulation.t('hint_low_brand');
            if (state.domainState.turnoverRate > 22) return window.mySimulation.t('hint_high_turnover');
            if (state.domainState.eNPS < 15) return window.mySimulation.t('hint_low_enps');
            if (state.currentPeriod === 4) return window.mySimulation.t('hint_crisis');
            return null;
        }

